id":"remote control","text":"remote control"},{"id":"button","text":"button"}]}},{"role":"listenRepeat","exercise":{"version":1,"id":"A22M6L1-M03","kind":"audio","title":"Listen and repeat","layout":"listen-repeat","audioPending":false,"items":[{"id":"1","text":"screen","audioId":"A22M6L1_M03-WORD-1","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-WORD-1.mp3?v=20261011-approved-final","example":"The photo is on the screen.","exampleAudioId":"A22M6L1_M03-EXAMPLE-1","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-EXAMPLE-1.mp3?v=20261011-approved-final"},{"id":"2","text":"button","audioId":"A22M6L1_M03-WORD-2","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-WORD-2.mp3?v=20261011-approved-final","example":"Press this button to start.","exampleAudioId":"A22M6L1_M03-EXAMPLE-2","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-EXAMPLE-2.mp3?v=20261011-approved-final"},{"id":"3","text":"cable","audioId":"A22M6L1_M03-WORD-3","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-WORD-3.mp3?v=20261011-approved-final","example":"Ben needs a longer cable.","exampleAudioId":"A22M6L1_M03-EXAMPLE-3","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-EXAMPLE-3.mp3?v=20261011-approved-final"},{"id":"4","text":"remote control","audioId":"A22M6L1_M03-WORD-4","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-WORD-4.mp3?v=20261011-approved-final","example":"Where’s the remote control?","exampleAudioId":"A22M6L1_M03-EXAMPLE-4","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-EXAMPLE-4.mp3?v=20261011-approved-final"},{"id":"5","text":"keyboard","audioId":"A22M6L1_M03-WORD-5","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-WORD-5.mp3?v=20261011-approved-final","example":"Her keyboard is next to the laptop.","exampleAudioId":"A22M6L1_M03-EXAMPLE-5","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-EXAMPLE-5.mp3?v=20261011-approved-final"},{"id":"6","text":"mouse","audioId":"A22M6L1_M03-WORD-6","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-WORD-6.mp3?v=20261011-approved-final","example":"This mouse doesn’t work.","exampleAudioId":"A22M6L1_M03-EXAMPLE-6","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a2-2/w6/l1/listen-repeat/M03-EXAMPLE-6.mp3?v=20261011-approved-final"}]}},{"role":"practice","exercise":{"version":1,"id":"A22M6L1-M04","kind":"gaps","title":"Complete the sentences.","inputMode":"text","items":[{"id":"1","segments":["Can you pass me the ",{"id":"1","answers":["remote control"]},"? I want to turn the TV off."]},{"id":"2","segments":["This ",{"id":"2","answers":["cable"]}," is too short. I can’t connect my laptop to the TV."]},{"id":"3","segments":["The picture on this ",{"id":"3","answers":["screen"]}," is very small. Can we use a bigger one?"]},{"id":"4","segments":["Press the green ",{"id":"4","answers":["button"]}," to start the computer."]},{"id":"5","segments":["There’s coffee on my ",{"id":"5","answers":["keyboard"]},". I can’t type!"]},{"id":"6","segments":["I move the ",{"id":"6","answers":["mouse"]},", but the arrow on the screen doesn’t move."]}]}},{"role":"rule","exercise":{"version":1,"id":"A22M6L1-M06","kind":"rule-page","title":"Something, anything, everything, nothing","blocks":[{"type":"text","text":"We use these words to talk about things without naming each one."},{"type":"text","title":"Something and anything","text":"Use something when there is a thing, but you don’t say exactly what it is:\nThere’s something on the screen. I can’t see what it is.\n\nIn questions, anything is useful when you don’t know the answer. We also use it after a negative verb:\nCan you see anything on the screen?\nI can’t see anything.\n\nSomething is possible in questions too. For example, “Would you like something to drink?” is an offer. A question does not always need anything.","highlights":["something","anything"]},{"type":"text","title":"Everything and nothing","text":"Everything means all the things we are talking about. If the screen, keyboard and mouse are all OK, we can say:\nEverything works.\n\nNothing means no thing. These two sentences have the same meaning:\nThere’s nothing on the screen.\nThere isn’t anything on the screen.\n\nNothing already makes the sentence negative. Don’t add not:\nNothing happens when I press the button.","highlights":["Everything","Nothing","nothing","isn’t anything","works","happens"]},{"type":"text","title":"The verb","text":"When one of these words is the subject, use the verb form for one thing:\nSomething is on the screen.\nEverything works.\nNothing happens.\nDoes anything happen when you press the button?","highlights":["is","works","happens","happen"]}]}},{"role":"practice","exercise":{"version":1,"id":"A22M6L1-M09","kind":"gaps","title":"Ready for a call","instruction":"Choose the correct words.","inputMode":"select","layout":"paragraph","items":[{"id":"1","segments":["I’m ready for my video call. I checked the screen, keyboard and mouse. They all work: ",{"id":"1","answers":["Everything"],"options":["Nothing","Everything","Anything"]}," works."]},{"id":"2","segments":["But now I can’t see my friend clearly. Something ",{"id":"2","answers":["is"],"options":["are","am","is"]}," on the screen. It’s a message in a red box."]},{"id":"3","segments":["I press the button to close it, but ",{"id":"3","answers":["nothing happens"],"options":["nothing happens","nothing happen","nothing doesn’t happen"]},". The message is still there."]},{"id":"4","segments":["My friend helps me close it. Now there ",{"id":"4","answers":["isn’t anything"],"options":["isn’t anything","isn’t nothing","aren’t anything"]}," covering the picture."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-1-1","kind":"writing","title":"Translate into English · 1.1","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"С экраном что-то не так.","normalization":"translation","acceptedAnswers":["There is something wrong with the screen.","Something is wrong with the screen.","there''s something wrong with the screen."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-1-2","kind":"writing","title":"Translate into English · 1.2","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Ты видишь что-нибудь на экране?","normalization":"translation","acceptedAnswers":["Can you see anything on the screen?","Do you see anything on the screen?"]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-1-3","kind":"writing","title":"Translate into English · 1.3","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Я ничего не вижу на экране.","normalization":"translation","acceptedAnswers":["I cannot see anything on the screen.","I do not see anything on the screen.","I can see nothing on the screen.","I see nothing on the screen.","I don''t see anything on the screen.","I can''t see anything on the screen."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-1-4","kind":"writing","title":"Translate into English · 1.4","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Я нажимаю кнопку, но ничего не происходит.","normalization":"translation","acceptedAnswers":["I press the button, but nothing happens.","I am pressing the button, but nothing is happening.","I press the button, but nothing is happening.","I am pressing the button, but nothing happens.","I push the button, but nothing happens.","I''m pressing the button, but nothing is happening.","I''m pressing the button, but nothing happens."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-1-5","kind":"writing","title":"Translate into English · 1.5","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Всё остальное работает нормально.","normalization":"translation","acceptedAnswers":["Everything else works fine.","Everything else works normally.","Everything else is working fine.","Everything else is working normally.","Everything else works well."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-2-1","kind":"writing","title":"Translate into English · 2.1","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"С клавиатурой что-то не так?","normalization":"translation","acceptedAnswers":["Is there something wrong with the keyboard?","Is anything wrong with the keyboard?","Is something wrong with the keyboard?"]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-2-2","kind":"writing","title":"Translate into English · 2.2","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Ты заметила что-нибудь необычное?","normalization":"translation","acceptedAnswers":["Did you notice anything unusual?","Have you noticed anything unusual?","Do you notice anything unusual?","Did you notice anything strange?","Have you noticed anything strange?"]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-2-3","kind":"writing","title":"Translate into English · 2.3","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Я не могу найти ничего плохого в кабеле.","normalization":"translation","acceptedAnswers":["I cannot find anything wrong with the cable.","I can find nothing wrong with the cable.","I cannot see anything wrong with the cable.","I can''t find anything wrong with the cable.","I can''t see anything wrong with the cable."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-2-4","kind":"writing","title":"Translate into English · 2.4","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Ничего не работает, когда я подключаю этот кабель.","normalization":"translation","acceptedAnswers":["Nothing works when I connect this cable.","Nothing works when I plug in this cable.","Nothing is working when I connect this cable.","Nothing is working when I plug in this cable."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-2-5","kind":"writing","title":"Translate into English · 2.5","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Сейчас всё работает?","normalization":"translation","acceptedAnswers":["Does everything work now?","Is everything working now?"]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-3-1","kind":"writing","title":"Translate into English · 3.1","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"На экране что-то появилось.","normalization":"translation","acceptedAnswers":["Something appeared on the screen.","Something has appeared on the screen.","Something came up on the screen."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-3-2","kind":"writing","title":"Translate into English · 3.2","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Что-нибудь происходит, когда ты нажимаешь эту кнопку?","normalization":"translation","acceptedAnswers":["Does anything happen when you press this button?","Is anything happening when you press this button?","Does anything happen when you push this button?"]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-3-3","kind":"writing","title":"Translate into English · 3.3","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Пульт ничего не меняет.","normalization":"translation","acceptedAnswers":["The remote control does not change anything.","The remote does not change anything.","The remote control changes nothing.","The remote changes nothing.","The remote control doesn''t change anything.","The remote doesn''t change anything."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-3-4","kind":"writing","title":"Translate into English · 3.4","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Я не могу сделать ничего с мышью.","normalization":"translation","acceptedAnswers":["I cannot do anything with the mouse.","I can do nothing with the mouse.","I cannot do anything using the mouse.","I can''t do anything with the mouse.","I can''t do anything using the mouse."]}]}},{"role":"translation","exercise":{"version":1,"id":"A22M6L1-HW-3-5","kind":"writing","title":"Translate into English · 3.5","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Всё подключено, но что-то всё ещё не работает.","normalization":"translation","acceptedAnswers":["Everything is connected, but something still does not work.","Everything is connected, but something still is not working.","Everything is plugged in, but something still does not work.","Everything is plugged in, but something still is not working.","Everything is connected, but something still isn''t working.","Everything is plugged in, but something still isn''t working.","Everything is connected, but something still doesn''t work.","Everything is plugged in, but something still doesn''t work."]}]}}],"reference":{"version":1,"id":"A22M6L1-M06","kind":"rule-page","title":"Something, anything, everything, nothing","blocks":[{"type":"text","text":"We use these words to talk about things without naming each one."},{"type":"text","title":"Something and anything","text":"Use something when there is a thing, but you don’t say exactly what it is:\nThere’s something on the screen. I can’t see what it is.\n\nIn questions, anything is useful when you don’t know the answer. We also use it after a negative verb:\nCan you see anything on the screen?\nI can’t see anything.\n\nSomething is possible in questions too. For example, “Would you like something to drink?” is an offer. A question does not always need anything.","highlights":["something","anything"]},{"type":"text","title":"Everything and nothing","text":"Everything means all the things we are talking about. If the screen, keyboard and mouse are all OK, we can say:\nEverything works.\n\nNothing means no thing. These two sentences have the same meaning:\nThere’s nothing on the screen.\nThere isn’t anything on the screen.\n\nNothing already makes the sentence negative. Don’t add not:\nNothing happens when I press the button.","highlights":["Everything","Nothing","nothing","isn’t anything","works","happens"]},{"type":"text","title":"The verb","text":"When one of these words is the subject, use the verb form for one thing:\nSomething is on the screen.\nEverything works.\nNothing happens.\nDoes anything happen when you press the button?","highlights":["is","works","happens","happen"]}]},"exercises":[{"version":1,"id":"A22M6L1-M02","kind":"matching","title":"Words","layout":"picture-word","instruction":"Match the pictures with the words.","items":[{"id":"A","text":"A","correctId":"screen","assetId":"A22M6L1_WORD_A","image":"Images/A2.1/biba_boba_computer_screen_an_adult_fingertip_pointing_to_the_a1945b42-9ee0-470e-b24b-3debf06846df_14.png","alt":"screen","imageWidth":496,"imageHeight":368},{"id":"B","text":"B","correctId":"cable","assetId":"A22M6L1_WORD_B","image":"Images/A2.1/biba_boba_USB_cable_a_flexible_cord_arranged_in_a_loose_curve_3e68d658-7430-4cfc-93f2-fc1d50f62020_9.png","alt":"cable","imageWidth":496,"imageHeight":368},{"id":"C","text":"C","correctId":"keyboard","assetId":"A22M6L1_WORD_C","image":"Images/A2.1/biba_boba_computer_keyboard_a_single_slim_desktop_keyboard_w_5cd54683-33cb-4329-a7a5-0fd8e603729c_13.png","alt":"keyboard","imageWidth":496,"imageHeight":368},{"id":"D","text":"D","correctId":"button","assetId":"A22M6L1_WORD_D","image":"Images/A2.1/biba_boba_button_an_adult_fingertip_pressing_the_edge_of_a_r_50bc609d-64fd-4f8f-895c-2ca8cfc7f6bd_23.png","alt":"button","imageWidth":496,"imageHeight":368},{"id":"E","text":"E","correctId":"mouse","assetId":"A22M6L1_WORD_E","image":"Images/A2.1/biba_boba_computer_mouse_a_simple_oval_computer_mouse_with_t_4e11da6e-50b9-4886-92a7-7e7b925234d8_17.png","alt":"mouse","imageWidth":496,"imageHeight":368},{"id":"F","text":"F","correctId":"remote control","assetId":"A22M6L1_WORD_F","image":"Images/A2.1/biba_boba_TV_remote_control_an_adult_hand_holding_a_slim_rec_8e676fe3-7857-4250-a653-6b04f87a06e0_21.png","alt":"remote control","imageWidth":496,"imageHeight":368}],"options":[{"id":"keyboard","text":"keyboard"},{"id":"cable","text":"cable"},{"id":"mouse","text":"mouse"},{"id":"screen","text":"screen"},{"id":"remote control","text":"remote control"},{"id":"button","text":"button"}]},{"version":1,"id":"A22M6L1-M04","kind":"gaps","title":"Complete the sentences.","inputMode":"text","items":[{"id":"1","segments":["Can you pass me the ",{"id":"1","answers":["remote control"]},"? I want to turn the TV off."]},{"id":"2","segments":["This ",{"id":"2","answers":["cable"]}," is too short. I can’t connect my laptop to the TV."]},{"id":"3","segments":["The picture on this ",{"id":"3","answers":["screen"]}," is very small. Can we use a bigger one?"]},{"id":"4","segments":["Press the green ",{"id":"4","answers":["button"]}," to start the computer."]},{"id":"5","segments":["There’s coffee on my ",{"id":"5","answers":["keyboard"]},". I can’t type!"]},{"id":"6","segments":["I move the ",{"id":"6","answers":["mouse"]},", but the arrow on the screen doesn’t move."]}]},{"version":1,"id":"A22M6L1-M09","kind":"gaps","title":"Ready for a call","instruction":"Choose the correct words.","inputMode":"select","layout":"paragraph","items":[{"id":"1","segments":["I’m ready for my video call. I checked the screen, keyboard and mouse. They all work: ",{"id":"1","answers":["Everything"],"options":["Nothing","Everything","Anything"]}," works."]},{"id":"2","segments":["But now I can’t see my friend clearly. Something ",{"id":"2","answers":["is"],"options":["are","am","is"]}," on the screen. It’s a message in a red box."]},{"id":"3","segments":["I press the button to close it, but ",{"id":"3","answers":["nothing happens"],"options":["nothing happens","nothing happen","nothing doesn’t happen"]},". The message is still there."]},{"id":"4","segments":["My friend helps me close it. Now there ",{"id":"4","answers":["isn’t anything"],"options":["isn’t anything","isn’t nothing","aren’t anything"]}," covering the picture."]}]},{"version":1,"id":"A22M6L1-HW-1-1","kind":"writing","title":"Translate into English · 1.1","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"С экраном что-то не так.","normalization":"translation","acceptedAnswers":["There is something wrong with the screen.","Something is wrong with the screen.","there''s something wrong with the screen."]}]},{"version":1,"id":"A22M6L1-HW-1-2","kind":"writing","title":"Translate into English · 1.2","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Ты видишь что-нибудь на экране?","normalization":"translation","acceptedAnswers":["Can you see anything on the screen?","Do you see anything on the screen?"]}]},{"version":1,"id":"A22M6L1-HW-1-3","kind":"writing","title":"Translate into English · 1.3","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Я ничего не вижу на экране.","normalization":"translation","acceptedAnswers":["I cannot see anything on the screen.","I do not see anything on the screen.","I can see nothing on the screen.","I see nothing on the screen.","I don''t see anything on the screen.","I can''t see anything on the screen."]}]},{"version":1,"id":"A22M6L1-HW-1-4","kind":"writing","title":"Translate into English · 1.4","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Я нажимаю кнопку, но ничего не происходит.","normalization":"translation","acceptedAnswers":["I press the button, but nothing happens.","I am pressing the button, but nothing is happening.","I press the button, but nothing is happening.","I am pressing the button, but nothing happens.","I push the button, but nothing happens.","I''m pressing the button, but nothing is happening.","I''m pressing the button, but nothing happens."]}]},{"version":1,"id":"A22M6L1-HW-1-5","kind":"writing","title":"Translate into English · 1.5","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Всё остальное работает нормально.","normalization":"translation","acceptedAnswers":["Everything else works fine.","Everything else works normally.","Everything else is working fine.","Everything else is working normally.","Everything else works well."]}]},{"version":1,"id":"A22M6L1-HW-2-1","kind":"writing","title":"Translate into English · 2.1","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"С клавиатурой что-то не так?","normalization":"translation","acceptedAnswers":["Is there something wrong with the keyboard?","Is anything wrong with the keyboard?","Is something wrong with the keyboard?"]}]},{"version":1,"id":"A22M6L1-HW-2-2","kind":"writing","title":"Translate into English · 2.2","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Ты заметила что-нибудь необычное?","normalization":"translation","acceptedAnswers":["Did you notice anything unusual?","Have you noticed anything unusual?","Do you notice anything unusual?","Did you notice anything strange?","Have you noticed anything strange?"]}]},{"version":1,"id":"A22M6L1-HW-2-3","kind":"writing","title":"Translate into English · 2.3","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Я не могу найти ничего плохого в кабеле.","normalization":"translation","acceptedAnswers":["I cannot find anything wrong with the cable.","I can find nothing wrong with the cable.","I cannot see anything wrong with the cable.","I can''t find anything wrong with the cable.","I can''t see anything wrong with the cable."]}]},{"version":1,"id":"A22M6L1-HW-2-4","kind":"writing","title":"Translate into English · 2.4","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Ничего не работает, когда я подключаю этот кабель.","normalization":"translation","acceptedAnswers":["Nothing works when I connect this cable.","Nothing works when I plug in this cable.","Nothing is working when I connect this cable.","Nothing is working when I plug in this cable."]}]},{"version":1,"id":"A22M6L1-HW-2-5","kind":"writing","title":"Translate into English · 2.5","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Сейчас всё работает?","normalization":"translation","acceptedAnswers":["Does everything work now?","Is everything working now?"]}]},{"version":1,"id":"A22M6L1-HW-3-1","kind":"writing","title":"Translate into English · 3.1","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"На экране что-то появилось.","normalization":"translation","acceptedAnswers":["Something appeared on the screen.","Something has appeared on the screen.","Something came up on the screen."]}]},{"version":1,"id":"A22M6L1-HW-3-2","kind":"writing","title":"Translate into English · 3.2","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Что-нибудь происходит, когда ты нажимаешь эту кнопку?","normalization":"translation","acceptedAnswers":["Does anything happen when you press this button?","Is anything happening when you press this button?","Does anything happen when you push this button?"]}]},{"version":1,"id":"A22M6L1-HW-3-3","kind":"writing","title":"Translate into English · 3.3","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Пульт ничего не меняет.","normalization":"translation","acceptedAnswers":["The remote control does not change anything.","The remote does not change anything.","The remote control changes nothing.","The remote changes nothing.","The remote control doesn''t change anything.","The remote doesn''t change anything."]}]},{"version":1,"id":"A22M6L1-HW-3-4","kind":"writing","title":"Translate into English · 3.4","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Я не могу сделать ничего с мышью.","normalization":"translation","acceptedAnswers":["I cannot do anything with the mouse.","I can do nothing with the mouse.","I cannot do anything using the mouse.","I can''t do anything with the mouse.","I can''t do anything using the mouse."]}]},{"version":1,"id":"A22M6L1-HW-3-5","kind":"writing","title":"Translate into English · 3.5","instruction":"Переведи предложение на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Всё подключено, но что-то всё ещё не работает.","normalization":"translation","acceptedAnswers":["Everything is connected, but something still does not work.","Everything is connected, but something still is not working.","Everything is plugged in, but something still does not work.","Everything is plugged in, but something still is not working.","Everything is connected, but something still isn''t working.","Everything is plugged in, but something still isn''t working.","Everything is connected, but something still doesn''t work.","Everything is plugged in, but something still doesn''t work."]}]}]}'::jsonb) on conflict(lesson_id) do update set definition=excluded.definition;
